#include "2mm.h"


void kernel_2mm(   
		double alpha,
		double beta,
		double tmp[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double C[ NJ + 0][NL + 0],
		double D[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B   offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=C   offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=D   offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=tmp   bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=B     bundle=control
#pragma HLS INTERFACE s_axilite port=C     bundle=control
#pragma HLS INTERFACE s_axilite port=D     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;

  int i, j, k;


  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
#pragma HLS PIPELINE
	tmp[i][j] = 0.0;
	for (k = 0; k < nk; ++k)
	  tmp[i][j] += alpha * A[i][k] * B[k][j];
      }
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
#pragma HLS PIPELINE
	D[i][j] *= beta;
	for (k = 0; k < nj; ++k)
	  D[i][j] += tmp[i][k] * C[k][j];
      }

}

#include "3mm.h"


void kernel_3mm(    
		double E[ NI + 0][NJ + 0],
		double A[ NI + 0][NK + 0],
		double B[ NK + 0][NJ + 0],
		double F[ NJ + 0][NL + 0],
		double C[ NJ + 0][NM + 0],
		double D[ NM + 0][NL + 0],
		double G[ NI + 0][NL + 0])
{
#pragma HLS INTERFACE m_axi port=E offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=F offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=D offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=G offset=slave bundle=gmem6

#pragma HLS INTERFACE s_axilite port=E bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=F bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=D bundle=control
#pragma HLS INTERFACE s_axilite port=G bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;
    const int nl = NL;
    const int nm = NM;

  int i, j, k;

  // E := A * B
  for (i = 0; i < ni; i++)
    for (j = 0; j < nj; j++)
      {
	double acc = 0.0;
	for (k = 0; k < nk; ++k)
	{
#pragma HLS PIPELINE II=1
	  acc += A[i][k] * B[k][j];
	}
	E[i][j] = acc;
      }

  // F := C * D
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      {
	double acc = 0.0;
	for (k = 0; k < nm; ++k)
	{
#pragma HLS PIPELINE II=1
	  acc += C[i][k] * D[k][j];
	}
	F[i][j] = acc;
      }

  // G := E * F
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      {
	double acc = 0.0;
	for (k = 0; k < nj; ++k)
	{
#pragma HLS PIPELINE II=1
	  acc += E[i][k] * F[k][j];
	}
	G[i][j] = acc;
      }

}

#include "atax.h"


void kernel_atax( 
		 double A[ M + 0][N + 0],
		 double x[ N + 0],
		 double y[ N + 0],
		 double tmp[ M + 0])
{
#pragma HLS INLINE off

    const int m = M;
    const int n = N;

  int i, j;

  for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    y[i] = 0;
  }

  for (i = 0; i < m; i++)
    {
      tmp[i] = 0.0;

      double acc = 0.0;
      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
	acc = acc + A[i][j] * x[j];
      }
      tmp[i] = acc;

      for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
	y[j] = y[j] + A[i][j] * tmp[i];
      }
    }

}

