#include "bicg.h"


void kernel_bicg( 
		 double A[ N + 0][M + 0],
		 double s[ M + 0],
		 double q[ N + 0],
		 double p[ M + 0],
		 double r[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=s offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=q offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=p offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=s bundle=control
#pragma HLS INTERFACE s_axilite port=q bundle=control
#pragma HLS INTERFACE s_axilite port=p bundle=control
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j;

  // Local buffers to enable banking / fast on-chip access
  double s_local[M];
  double p_local[M];
  double r_local[N];
#pragma HLS ARRAY_PARTITION variable=s_local cyclic factor=8 dim=1
#pragma HLS ARRAY_PARTITION variable=p_local cyclic factor=8 dim=1

  // Stage p into local memory (reused across all i iterations)
  load_p: for (j = 0; j < m; j++) {
#pragma HLS PIPELINE II=1
    p_local[j] = p[j];
  }

  // Stage r into local memory
  load_r: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    r_local[i] = r[i];
  }

  // Initialize s accumulator
  init_s: for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
    s_local[i] = 0;
  }

  main_i: for (i = 0; i < n; i++)
    {
      double q_acc = 0.0;
      double ri = r_local[i];

      inner_j: for (j = 0; j < m; j++)
	{
#pragma HLS PIPELINE II=1
	  double a = A[i][j];
	  s_local[j] = s_local[j] + ri * a;        // independent across j
	  q_acc = q_acc + a * p_local[j];          // serial reduction, order preserved
	}

      q[i] = q_acc;
    }

  // Write back s accumulator
  store_s: for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
    s[i] = s_local[i];
  }

}

#include "cholesky.h"


void kernel_cholesky(
		     double A[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;


  for (i = 0; i < n; i++) {

     for (j = 0; j < i; j++) {
        for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
           A[i][j] -= A[i][k] * A[j][k];
        }
        A[i][j] /= A[j][j];
     }

     for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
        A[i][i] -= A[i][k] * A[i][k];
     }
     A[i][i] = sqrt(A[i][i]);
  }

}

#include "correlation.h"


void kernel_correlation( 
			double float_n,
			double data[ N + 0][M + 0],
			double corr[ M + 0][M + 0],
			double mean[ M + 0],
			double stddev[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=corr offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=stddev offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data bundle=control
#pragma HLS INTERFACE s_axilite port=corr bundle=control
#pragma HLS INTERFACE s_axilite port=mean bundle=control
#pragma HLS INTERFACE s_axilite port=stddev bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;
    const int m = M;

  int i, j, k;

  double eps = 0.1;


  for (j = 0; j < m; j++)
    {
      mean[j] = 0.0;
      // Serial FP reduction: keep ordering, pipeline body only.
      for (i = 0; i < n; i++)
      {
#pragma HLS PIPELINE
	mean[j] += data[i][j];
      }
      mean[j] /= float_n;
    }


   for (j = 0; j < m; j++)
    {
      stddev[j] = 0.0;
      // Serial FP reduction: keep ordering, pipeline body only.
      for (i = 0; i < n; i++)
      {
#pragma HLS PIPELINE
        stddev[j] += (data[i][j] - mean[j]) * (data[i][j] - mean[j]);
      }
      stddev[j] /= float_n;
      stddev[j] = sqrt(stddev[j]);


      stddev[j] = stddev[j] <= eps ? 1.0 : stddev[j];
    }


  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
      {
#pragma HLS PIPELINE
        data[i][j] -= mean[j];
        data[i][j] /= sqrt(float_n) * stddev[j];
      }


  for (i = 0; i < m-1; i++)
    {
      corr[i][i] = 1.0;
      for (j = i+1; j < m; j++)
        {
          corr[i][j] = 0.0;
          // Serial FP reduction: keep ordering, pipeline body only.
          for (k = 0; k < n; k++)
          {
#pragma HLS PIPELINE
            corr[i][j] += (data[k][i] * data[k][j]);
          }
          corr[j][i] = corr[i][j];
        }
    }
  corr[m-1][m-1] = 1.0;

}

#include "gemver.h"


extern "C" {
void kernel_gemver(
		   double alpha,
		   double beta,
		   double A[ N + 0][N + 0],
		   double u1[ N + 0],
		   double v1[ N + 0],
		   double u2[ N + 0],
		   double v2[ N + 0],
		   double w[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0],
		   double z[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=u1  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=v1  offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=u2  offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=v2  offset=slave bundle=gmem4
#pragma HLS INTERFACE m_axi port=w   offset=slave bundle=gmem5
#pragma HLS INTERFACE m_axi port=x   offset=slave bundle=gmem6
#pragma HLS INTERFACE m_axi port=y   offset=slave bundle=gmem7
#pragma HLS INTERFACE m_axi port=z   offset=slave bundle=gmem8

#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta  bundle=control
#pragma HLS INTERFACE s_axilite port=A     bundle=control
#pragma HLS INTERFACE s_axilite port=u1    bundle=control
#pragma HLS INTERFACE s_axilite port=v1    bundle=control
#pragma HLS INTERFACE s_axilite port=u2    bundle=control
#pragma HLS INTERFACE s_axilite port=v2    bundle=control
#pragma HLS INTERFACE s_axilite port=w     bundle=control
#pragma HLS INTERFACE s_axilite port=x     bundle=control
#pragma HLS INTERFACE s_axilite port=y     bundle=control
#pragma HLS INTERFACE s_axilite port=z     bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j;

  // ---- Stage 1: A = A + u1*v1' + u2*v2'  (fully independent per element) ----
  L1_i: for (i = 0; i < n; i++) {
    double u1i = u1[i];
    double u2i = u2[i];
    L1_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      A[i][j] = A[i][j] + u1i * v1[j] + u2i * v2[j];
    }
  }

  // ---- Stage 2: x[i] += beta * A[j][i] * y[j]  (serial FP reduction) ----
  // Keep accumulation order bit-exact: pipeline body, do not reassociate.
  L2_i: for (i = 0; i < n; i++) {
    double xi = x[i];
    L2_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      xi = xi + beta * A[j][i] * y[j];
    }
    x[i] = xi;
  }

  // ---- Stage 3: x[i] += z[i]  (independent per element) ----
  L3_i: for (i = 0; i < n; i++) {
#pragma HLS PIPELINE II=1
    x[i] = x[i] + z[i];
  }

  // ---- Stage 4: w[i] += alpha * A[i][j] * x[j]  (serial FP reduction) ----
  L4_i: for (i = 0; i < n; i++) {
    double wi = w[i];
    L4_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      wi = wi + alpha * A[i][j] * x[j];
    }
    w[i] = wi;
  }

}
}

#include "ludcmp.h"


void kernel_ludcmp(
		   double A[ N + 0][N + 0],
		   double b[ N + 0],
		   double x[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=b offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=b bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  double w;

  for (i = 0; i < n; i++) {
    for (j = 0; j <i; j++) {
       w = A[i][j];
       for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
          w -= A[i][k] * A[k][j];
       }
        A[i][j] = w / A[j][j];
    }
   for (j = i; j < n; j++) {
       w = A[i][j];
       for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
          w -= A[i][k] * A[k][j];
       }
       A[i][j] = w;
    }
  }

  for (i = 0; i < n; i++) {
     w = b[i];
     for (j = 0; j < i; j++) {
#pragma HLS PIPELINE II=1
        w -= A[i][j] * y[j];
     }
     y[i] = w;
  }

   for (i = n-1; i >=0; i--) {
     w = y[i];
     for (j = i+1; j < n; j++) {
#pragma HLS PIPELINE II=1
        w -= A[i][j] * x[j];
     }
     x[i] = w / A[i][i];
  }

}

#include "mvt.h"


void kernel_mvt(
		double x1[ N + 0],
		double x2[ N + 0],
		double y_1[ N + 0],
		double y_2[ N + 0],
		double A[ N + 0][N + 0])
{
#pragma HLS INLINE off

    const int n = N;

  int i, j;

  loop_i1: for (i = 0; i < n; i++) {
    double acc1 = x1[i];
    loop_j1: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc1 = acc1 + A[i][j] * y_1[j];
    }
    x1[i] = acc1;
  }

  loop_i2: for (i = 0; i < n; i++) {
    double acc2 = x2[i];
    loop_j2: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      acc2 = acc2 + A[j][i] * y_2[j];
    }
    x2[i] = acc2;
  }

}


