#pragma HLS PIPELINE II=1
      C[i][j] *= beta;
    }
    for (k = 0; k < m; k++) {
      for (j = 0; j <= i; j++) {
#pragma HLS PIPELINE II=1
        C[i][j] += alpha * A[i][k] * A[j][k];
      }
    }
  }

}

