void kernel_covariance( 
		       double float_n,
		       double data[ N + 0][M + 0],
		       double cov[ M + 0][M + 0],
		       double mean[ M + 0])
{
#pragma HLS INTERFACE m_axi port=data offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=cov  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=mean offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=float_n bundle=control
#pragma HLS INTERFACE s_axilite port=data    bundle=control
#pragma HLS INTERFACE s_axilite port=cov     bundle=control
#pragma HLS INTERFACE s_axilite port=mean    bundle=control
#pragma HLS INTERFACE s_axilite port=return  bundle=control


    const int n = N;
    const int m = M;

  int i, j, k;

  for (j = 0; j < m; j++)
    {
      mean[j] = 0.0;
      for (i = 0; i < n; i++)
      {
#pragma HLS PIPELINE II=1
        // serial FP reduction kept in-order (no reassociation)
        mean[j] += data[i][j];
      }
      mean[j] /= float_n;
    }

  for (i = 0; i < n; i++)
    for (j = 0; j < m; j++)
    {
#pragma HLS PIPELINE II=1
      data[i][j] -= mean[j];
    }

  for (i = 0; i < m; i++)
    for (j = i; j < m; j++)
      {
        cov[i][j] = 0.0;
        for (k = 0; k < n; k++)
        {
#pragma HLS PIPELINE II=1
          // serial FP reduction kept in-order (no reassociation)
          cov[i][j] += data[k][i] * data[k][j];
        }
        cov[i][j] /= (float_n - 1.0);
        cov[j][i] = cov[i][j];
      }

}

#include "doitgen.h"

extern "C" {
void kernel_doitgen(
		    double A[ NR + 0][NQ + 0][NP + 0],
		    double C4[ NP + 0][NP + 0],
		    double sum[ NP + 0])
{
#pragma HLS INTERFACE m_axi port=A   offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=C4  offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=sum offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A   bundle=control
#pragma HLS INTERFACE s_axilite port=C4  bundle=control
#pragma HLS INTERFACE s_axilite port=sum bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int nr = NR;
    const int nq = NQ;
    const int np = NP;

  int r, q, p, s;

  // Local staging buffers to enable reuse and parallel access.
  double C4_local[NP][NP];
#pragma HLS ARRAY_PARTITION variable=C4_local complete dim=1

  double A_row[NP];
#pragma HLS ARRAY_PARTITION variable=A_row complete dim=1

  double sum_local[NP];
#pragma HLS ARRAY_PARTITION variable=sum_local complete dim=1

  // Stage C4 once; it is reused across all (r,q).
  for (s = 0; s < np; s++) {
    for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
      C4_local[s][p] = C4[s][p];
    }
  }

  for (r = 0; r < nr; r++) {
    for (q = 0; q < nq; q++)  {

      // Load the current A[r][q][*] row into local memory.
      for (s = 0; s < np; s++) {
#pragma HLS PIPELINE II=1
        A_row[s] = A[r][q][s];
      }

      // Compute sum[p] = reduction over s of A_row[s]*C4[s][p].
      // The reduction over s is kept serial (FP order-preserving).
      // The loop over p is independent and is unrolled for parallelism.
      for (p = 0; p < np; p++) {
#pragma HLS UNROLL
        sum_local[p] = 0.0;
      }

      for (s = 0; s < np; s++) {
#pragma HLS PIPELINE II=1
        double a_s = A_row[s];
        for (p = 0; p < np; p++) {
#pragma HLS UNROLL
          // Each p has its own independent serial accumulator over s,
          // preserving the original reduction order per output element.
          sum_local[p] += a_s * C4_local[s][p];
        }
      }

      // Write back results.
      for (p = 0; p < np; p++) {
#pragma HLS PIPELINE II=1
        sum[p]      = sum_local[p];
        A[r][q][p]  = sum_local[p];
      }
    }
  }

}
}

#include "durbin.h"


void kernel_durbin(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INLINE off

    const int n = N;

 double z[N];
 double alpha;
 double beta;
 double sum;

 int i,k;

 y[0] = -r[0];
 beta = 1.0;
 alpha = -r[0];

 for (k = 1; k < n; k++) {
   beta = (1-alpha*alpha)*beta;
   sum = 0.0;
   // Serial FP reduction: keep order preserving for bit-exact result.
   for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
      sum += r[k-i-1]*y[i];
   }
   alpha = - (r[k] + sum)/beta;

   // Independent iterations: read from y, write to z.
   for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
      z[i] = y[i] + alpha*y[k-i-1];
   }
   for (i=0; i<k; i++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=1 max=N
     y[i] = z[i];
   }
   y[k] = alpha;
 }

}


extern "C" {
void workload(
		   double r[ N + 0],
		   double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=r offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem1
#pragma HLS INTERFACE s_axilite port=r bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    kernel_durbin(r, y);
}
}

#include "fdtd-2d.h"


void kernel_fdtd_2d(


		    double ex[ NX + 0][NY + 0],
		    double ey[ NX + 0][NY + 0],
		    double hz[ NX + 0][NY + 0],
		    double _fict_[ TMAX + 0])
{
#pragma HLS INTERFACE m_axi port=ex     offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=ey     offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=hz     offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=_fict_ offset=slave bundle=gmem3
#pragma HLS INTERFACE s_axilite port=ex     bundle=control
#pragma HLS INTERFACE s_axilite port=ey     bundle=control
#pragma HLS INTERFACE s_axilite port=hz     bundle=control
#pragma HLS INTERFACE s_axilite port=_fict_ bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control


    const int tmax = TMAX;
    const int nx = NX;
    const int ny = NY;

  int t, i, j;


  for(t = 0; t < tmax; t++)
    {
      for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	ey[0][j] = _fict_[t];
      }
      for (i = 1; i < nx; i++)
	for (j = 0; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ey[i][j] = ey[i][j] - 0.5*(hz[i][j]-hz[i-1][j]);
	}
      for (i = 0; i < nx; i++)
	for (j = 1; j < ny; j++) {
#pragma HLS PIPELINE II=1
	  ex[i][j] = ex[i][j] - 0.5*(hz[i][j]-hz[i][j-1]);
	}
      for (i = 0; i < nx - 1; i++)
	for (j = 0; j < ny - 1; j++) {
#pragma HLS PIPELINE II=1
	  hz[i][j] = hz[i][j] - 0.7*  (ex[i][j+1] - ex[i][j] +
				       ey[i+1][j] - ey[i][j]);
	}
    }

}

#include "floyd-warshall.h"


void kernel_floyd_warshall(
			   int path[ N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=path offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=path bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j, k;

  // Local buffer to enable fast on-chip access and parallel ports
  static int buf[N][N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=16 dim=2

  // Stage data into local memory
  load_i: for (i = 0; i < n; i++) {
    load_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      buf[i][j] = path[i][j];
    }
  }

  k_loop: for (k = 0; k < n; k++)
    {
      i_loop: for (i = 0; i < n; i++) {
	// Cache path[i][k] which is invariant across the j loop
	int pik = buf[i][k];
	j_loop: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
#pragma HLS UNROLL factor=16
	  int pij = buf[i][j];
	  int pkj = buf[k][j];
	  int sum = pik + pkj;
	  buf[i][j] = pij < sum ? pij : sum;
	}
      }
    }

  // Write results back to global memory
  store_i: for (i = 0; i < n; i++) {
    store_j: for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
      path[i][j] = buf[i][j];
    }
  }

}

#include "gemm.h"


void kernel_gemm(  
		 double alpha,
		 double beta,
		 double C[ NI + 0][NJ + 0],
		 double A[ NI + 0][NK + 0],
		 double B[ NK + 0][NJ + 0])
{
#pragma HLS INTERFACE m_axi port=C offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=C bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int ni = NI;
    const int nj = NJ;
    const int nk = NK;

  int i, j, k;

  // Stage the full B matrix into local BRAM once (reused across all rows of C).
  static double B_local[NK][NJ];
  for (k = 0; k < nk; k++) {
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      B_local[k][j] = B[k][j];
    }
  }

  for (i = 0; i < ni; i++) {
    // Local row buffers to eliminate per-iteration AXI traffic in the hot loop.
    double C_row[NJ];
    double A_row[NK];

    // Load row i of A into local memory.
    for (k = 0; k < nk; k++) {
#pragma HLS PIPELINE II=1
      A_row[k] = A[i][k];
    }

    // Load and scale row i of C.
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      C_row[j] = C[i][j] * beta;
    }

    // Compute. Accumulation order over k is preserved exactly (serial),
    // so the bit-exact result matches the original kernel.
    for (k = 0; k < nk; k++) {
      double a_val = alpha * A_row[k];
      for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
        // Inner loop touches distinct C_row[j] elements each iteration,
        // so no same-address loop-carried dependence within this loop.
        C_row[j] += a_val * B_local[k][j];
      }
    }

    // Write row i of C back to global memory.
    for (j = 0; j < nj; j++) {
#pragma HLS PIPELINE II=1
      C[i][j] = C_row[j];
    }
  }

}

#include "gesummv.h"


void kernel_gesummv(
		    double alpha,
		    double beta,
		    double A[ N + 0][N + 0],
		    double B[ N + 0][N + 0],
		    double tmp[ N + 0],
		    double x[ N + 0],
		    double y[ N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=B offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=tmp offset=slave bundle=gmem2
#pragma HLS INTERFACE m_axi port=x offset=slave bundle=gmem3
#pragma HLS INTERFACE m_axi port=y offset=slave bundle=gmem4
#pragma HLS INTERFACE s_axilite port=alpha bundle=control
#pragma HLS INTERFACE s_axilite port=beta bundle=control
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=B bundle=control
#pragma HLS INTERFACE s_axilite port=tmp bundle=control
#pragma HLS INTERFACE s_axilite port=x bundle=control
#pragma HLS INTERFACE s_axilite port=y bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    const int n = N;

  int i, j;

  // Stage x into a local buffer for fast, parallel-friendly reuse across rows
  double x_local[N];
#pragma HLS ARRAY_PARTITION variable=x_local cyclic factor=4 dim=1
  for (j = 0; j < n; j++) {
#pragma HLS PIPELINE II=1
    x_local[j] = x[j];
  }

  for (i = 0; i < n; i++)
    {
      double acc_tmp = 0.0;
      double acc_y = 0.0;

      for (j = 0; j < n; j++)
	{
#pragma HLS PIPELINE II=1
	  // Preserve serial accumulation order to keep bit-exact results
	  acc_tmp = A[i][j] * x_local[j] + acc_tmp;
	  acc_y   = B[i][j] * x_local[j] + acc_y;
	}

      tmp[i] = acc_tmp;
      y[i] = alpha * acc_tmp + beta * acc_y;
    }

}

#include "gramschmidt.h"


void kernel_gramschmidt(
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{


    const int m = M;
    const int n = N;

  int i, j, k;

  double nrm;

  for (k = 0; k < n; k++)
    {
      nrm = 0.0;
    nrm_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        nrm += A[i][k] * A[i][k];
      }
      R[k][k] = sqrt(nrm);

    q_loop:
      for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
        Q[i][k] = A[i][k] / R[k][k];
      }

    j_loop:
      for (j = k + 1; j < n; j++)
	{
	  R[k][j] = 0.0;
	dot_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    R[k][j] += Q[i][k] * A[i][j];
	  }
	update_loop:
	  for (i = 0; i < m; i++) {
#pragma HLS PIPELINE II=1
	    A[i][j] = A[i][j] - Q[i][k] * R[k][j];
	  }
	}
    }

}


extern "C" {
void workload(
			double A[ M + 0][N + 0],
			double R[ N + 0][N + 0],
			double Q[ M + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem0
#pragma HLS INTERFACE m_axi port=R offset=slave bundle=gmem1
#pragma HLS INTERFACE m_axi port=Q offset=slave bundle=gmem2
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=R bundle=control
#pragma HLS INTERFACE s_axilite port=Q bundle=control
